import {pool,sprite,odds,sameLine} from './pokemon.js';
import {types,TIER_NAMES,tierOf,zonePool,teamAfterDrop,teamAfterEquip} from './world.js';
import {typeColor} from './fight.js';
import {TYPE_FR} from './battle.js';
const fmt=n=>n.toLocaleString('fr-FR');
const compact=n=>n>=1e9?(n/1e9).toLocaleString('fr-FR',{maximumFractionDigits:2})+' Md':n>=1e6?(n/1e6).toLocaleString('fr-FR',{maximumFractionDigits:1})+' M':n>=1e3?(n/1e3).toLocaleString('fr-FR',{maximumFractionDigits:1})+' k':fmt(n);
const tierColors=['','#9ddd83','#7dccff','#cfacff','#ffb578','#ffe179'];
const typeBadges=id=>types[id].map(t=>`<span class="catalog-type" style="--type-color:${typeColor(t)}">${TYPE_FR[t]||t}</span>`).join('');
const typeOptions=()=>Object.entries(TYPE_FR).filter(([key])=>Object.values(types).some(ts=>ts.includes(key))).map(([key,name])=>`<option value="${key}">${name}</option>`).join('');
const rarityOptions=()=>TIER_NAMES.slice(1).map((name,i)=>`<option value="${i+1}">${name}</option>`).join('');
const pager=()=>'<div class="catalog-pagination"><button type="button" data-page="-1" aria-label="Page précédente">← Précédente</button><span data-page-label></span><button type="button" data-page="1" aria-label="Page suivante">Suivante →</button></div>';
function filterEntries(entries,query,type,tier){const q=query.trim().toLocaleLowerCase('fr');return entries.filter(p=>(p.name.toLocaleLowerCase('fr').includes(q)||String(p.id).padStart(3,'0').includes(q.replace(/^#/,'')))&&(!type||types[p.id].includes(type))&&(!tier||tierOf(p.id)===+tier));}
export function mountCollection(container,{getState,level,power,onTeam,onProfile}){
 container.innerHTML=`<div class="collection-studio"><section class="roster-area"><div class="catalog-section-head"><div><span class="catalog-eyebrow">ÉQUIPE DE CHAMPIONS</span><h3>Mon équipe <span id="roster-count"></span></h3></div><div class="catalog-total">Puissance d’équipe<strong id="roster-total"></strong></div></div><div class="roster" aria-label="Les six emplacements de mon équipe"></div><p class="catalog-help">Glisse un Pokémon vers une case pour l’équiper ou échanger sa place. Tu peux aussi le sélectionner puis cliquer sur une case. Une forme par lignée.</p></section><section class="collection-library"><div class="catalog-section-head"><h3>Ma collection</h3><span id="library-count"></span></div><div class="catalog-filters"><label>Rechercher<input type="search" placeholder="Nom ou numéro…" data-search></label><label>Type<select data-type><option value="">Tous les types</option>${typeOptions()}</select></label><label>Rareté<select data-tier><option value="">Toutes les raretés</option>${rarityOptions()}</select></label><label>Trier<select data-sort><option value="power">Puissance ↓</option><option value="level">Niveau ↓</option><option value="name">Nom A–Z</option><option value="number">N° Pokédex</option></select></label></div><div class="catalog-selection" role="status" aria-live="polite">Sélectionne un Pokémon ou fais-le glisser vers ton équipe.</div><div class="library-grid"></div>${pager()}</section></div>`;
 const root=container.querySelector('.collection-studio'),$=s=>root.querySelector(s);
 let query='',type='',tier='',sort='power',page=0,selected=null,dragId=null,touch=null,ignoreClick=false;
 function details(p){const l=level(p.id);return `<span class="catalog-card-top"><span>#${String(p.id).padStart(3,'0')}</span><span style="color:${tierColors[tierOf(p.id)]}">${TIER_NAMES[tierOf(p.id)]}</span></span><img class="catalog-sprite" src="${sprite(p.id)}" alt="" loading="lazy"><strong class="catalog-name">${p.name}</strong><span class="catalog-types">${typeBadges(p.id)}</span><span class="catalog-level">Niv. ${l.level} <small>/ ${l.cap}${l.capped?' · MAX':''}</small></span><span class="catalog-power" title="${fmt(power(p.id))} points de puissance">✦ ${compact(power(p.id))} <small>puissance</small></span><span class="catalog-xp"><i style="width:${l.capped?100:l.xp/l.need*100}%"></i></span><small class="catalog-xp-text">${l.capped?(l.evolvesAt?'Tire l’évolution pour progresser':'Niveau maximum'):fmt(l.xp)+' / '+fmt(l.need)+' XP'}</small>`;}
 function render(){const state=getState();$('#roster-count').textContent=state.team.length+' / 6';$('#roster-total').textContent=compact(state.team.reduce((sum,id)=>sum+power(id),0));
 $('.roster').innerHTML=Array.from({length:6},(_,i)=>{const p=pool.find(p=>p.id===state.team[i]);return `<article class="roster-card ${p?'':'empty'}" ${p?`style="--pokemon-color:${typeColor(types[p.id][0])}"`:''}><button type="button" class="roster-pick" data-slot="${i}" ${p?`data-drag-id="${p.id}" draggable="true" aria-pressed="${selected===p.id}"`:''} aria-label="Emplacement ${i+1}${p?' : '+p.name:' libre'}"><span class="catalog-slot">${i===0?'EN TÊTE':'CASE '+(i+1)}</span>${p?details(p):'<span class="roster-plus">＋</span><strong>Emplacement libre</strong><small>Dépose un Pokémon ici</small>'}</button>${p?`<div class="catalog-card-actions"><button type="button" data-detail="${p.id}">Profil</button><button type="button" data-remove="${p.id}" aria-label="Retirer ${p.name}">Retirer</button><button type="button" class="catalog-grip" data-grip="${p.id}" aria-label="Déplacer ${p.name}">⠿</button></div>`:''}</article>`;}).join('');
 const all=pool.filter(p=>state.counts[p.id]&&!state.team.includes(p.id)),entries=filterEntries(all,query,type,tier).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'fr'):sort==='number'?a.id-b.id:sort==='level'?level(b.id).level-level(a.id).level||power(b.id)-power(a.id):power(b.id)-power(a.id));
 const pages=Math.max(1,Math.ceil(entries.length/10));page=Math.min(page,pages-1);$('#library-count').textContent=entries.length+' espèce'+(entries.length>1?'s':'')+' disponible'+(entries.length>1?'s':'');
 $('.library-grid').innerHTML=entries.length?entries.slice(page*10,page*10+10).map(p=>`<article class="library-card" style="--pokemon-color:${typeColor(types[p.id][0])}"><button type="button" class="library-pick" data-select="${p.id}" data-drag-id="${p.id}" draggable="true" aria-pressed="${selected===p.id}" aria-label="Sélectionner ${p.name}">${details(p)}<small class="catalog-copies">×${fmt(state.counts[p.id])} rencontré${state.counts[p.id]>1?'s':''}</small></button><div class="catalog-card-actions"><button type="button" data-detail="${p.id}">Profil</button><button type="button" data-add="${p.id}">${state.team.some(id=>sameLine(id,p.id))?'Remplacer':'Équiper'}</button><button type="button" class="catalog-grip" data-grip="${p.id}" aria-label="Déplacer ${p.name}">⠿</button></div></article>`).join(''):'<p class="catalog-empty">'+(all.length?'Aucun Pokémon avec ces filtres.':'Tes autres Pokémon apparaîtront ici après tes captures.')+'</p>';
 $('[data-page-label]').textContent='Page '+(page+1)+' / '+pages;$('[data-page="-1"]').disabled=page===0;$('[data-page="1"]').disabled=page===pages-1;
 }
 function notify(text){$('.catalog-selection').textContent=text;}
 function choose(id){selected=id;render();notify(pool[id-1].name+' sélectionné : choisis sa case dans l’équipe.');$('.roster').scrollIntoView({block:'nearest',behavior:getState().reducedMotion?'instant':'smooth'});}
 function drop(id,slot){if(!getState().counts[id])return;selected=null;onTeam(teamAfterDrop(getState().team,id,slot));notify(pool[id-1].name+' placé dans l’équipe.');}
 root.onclick=e=>{if(ignoreClick)return;const b=e.target.closest('button');if(!b)return;if(b.dataset.select)choose(+b.dataset.select);else if(b.dataset.slot!==undefined){const slot=+b.dataset.slot;if(selected!==null)drop(selected,slot);else if(getState().team[slot])choose(getState().team[slot]);}else if(b.dataset.detail)onProfile(+b.dataset.detail);else if(b.dataset.remove){onTeam(getState().team.filter(id=>id!==+b.dataset.remove));selected=null;notify('Pokémon remis dans la collection.');}else if(b.dataset.add){const id=+b.dataset.add,state=getState();if(state.team.length===6&&!state.team.some(m=>sameLine(m,id)))choose(id);else{selected=null;onTeam(teamAfterEquip(state.team,id));notify(pool[id-1].name+' équipé.');}}else if(b.dataset.page){page+=+b.dataset.page;render();}else if(b.dataset.grip)choose(+b.dataset.grip);};
 root.oninput=e=>{if(e.target.matches('[data-search]')){query=e.target.value;page=0;render();}};root.onchange=e=>{if(e.target.matches('[data-type]'))type=e.target.value;else if(e.target.matches('[data-tier]'))tier=e.target.value;else if(e.target.matches('[data-sort]'))sort=e.target.value;else return;page=0;render();};
 function clearDrop(){root.querySelectorAll('.drop-target').forEach(el=>el.classList.remove('drop-target'));}
 root.ondragstart=e=>{const b=e.target.closest('[data-drag-id]');if(!b)return;dragId=+b.dataset.dragId;e.dataTransfer.setData('text/plain',String(dragId));e.dataTransfer.effectAllowed='move';};
 root.ondragover=e=>{const slot=e.target.closest('[data-slot]');if(slot&&dragId!==null){e.preventDefault();e.dataTransfer.dropEffect='move';clearDrop();slot.classList.add('drop-target');}};root.ondrop=e=>{const slot=e.target.closest('[data-slot]');if(slot&&dragId!==null){e.preventDefault();drop(dragId,+slot.dataset.slot);}dragId=null;clearDrop();};root.ondragend=()=>{dragId=null;clearDrop();};
 // La poignée permet aussi le dépôt tactile sans bloquer le défilement sur les cartes.
 root.onpointerdown=e=>{const grip=e.target.closest('[data-grip]');if(!grip)return;touch={id:e.pointerId,pokemon:+grip.dataset.grip,startX:e.clientX,startY:e.clientY,moved:false};grip.setPointerCapture(e.pointerId);};
 root.onpointermove=e=>{if(!touch||touch.id!==e.pointerId)return;touch.moved ||= Math.hypot(e.clientX-touch.startX,e.clientY-touch.startY)>8;if(!touch.moved)return;const slot=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-slot]');clearDrop();if(slot&&root.contains(slot))slot.classList.add('drop-target');};
 root.onpointerup=e=>{if(!touch||touch.id!==e.pointerId)return;const t=touch;touch=null;clearDrop();if(t.moved){const slot=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-slot]');ignoreClick=true;setTimeout(()=>ignoreClick=false,0);if(slot&&root.contains(slot))drop(t.pokemon,+slot.dataset.slot);}};root.onpointercancel=()=>{touch=null;clearDrop();};
 render();return {refresh:render};
}

export function mountZoneIndex(container,{getState,getZone,onProfile}){
 const zone=getZone(),all=zonePool(zone.id);
 container.innerHTML=`<div class="zone-catalog"><div class="catalog-section-head"><div><span class="catalog-eyebrow">CARNET DE RARETÉS</span><p>${zone.note}</p></div><span class="zone-completion"></span></div><div class="catalog-filters"><label>Rechercher<input type="search" placeholder="Nom ou numéro…" data-search></label><label>Type<select data-type><option value="">Tous les types</option>${typeOptions()}</select></label><label>Rareté<select data-tier><option value="">Toutes les raretés</option>${rarityOptions()}</select></label><label>Trier<select data-sort><option value="chance">Chance ↓</option><option value="name">Nom A–Z</option><option value="number">N° Pokédex</option></select></label></div><div class="zone-status-filters" role="group" aria-label="Découvertes"><button type="button" data-status="all" aria-pressed="true">Tous</button><button type="button" data-status="owned" aria-pressed="false">Découverts</button><button type="button" data-status="missing" aria-pressed="false">À découvrir</button></div><div class="zone-rarity-board"></div>${pager()}<p class="catalog-help">Les probabilités sont propres à cette zone. Les silhouettes restent masquées jusqu’à la première capture. Catégories et équilibrage provisoires.</p></div>`;
 const root=container.querySelector('.zone-catalog'),$=s=>root.querySelector(s);let query='',type='',tier='',sort='chance',status='all',page=0;
 function render(){const state=getState(),entries=filterEntries(all,query,type,tier).filter(p=>status==='all'||!!state.counts[p.id]===(status==='owned')).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name,'fr'):sort==='number'?a.id-b.id:b.probability-a.probability);
 $('.zone-completion').textContent=all.filter(p=>state.counts[p.id]).length+' / '+all.length+' découverts';
 // Chaque catégorie a sa propre tranche sur la page : les légendaires sont visibles dès la première page.
 const tiers=tier?[+tier]:[1,2,3,4,5],size=t=>t===5?5:4,pages=Math.max(1,...tiers.map(t=>Math.ceil(entries.filter(p=>p.tier===t).length/size(t))));page=Math.min(page,pages-1);
 $('.zone-rarity-board').innerHTML=tiers.map(t=>{const group=entries.filter(p=>p.tier===t),available=all.some(p=>p.tier===t),share=zone.shares[t-1]||0;return `<section class="zone-rarity-column" style="--rarity-color:${tierColors[t]}"><header><h3>${TIER_NAMES[t]}</h3><span>${(share*100).toLocaleString('fr-FR',{maximumFractionDigits:1})} % des tirages</span><small>${group.length} espèce${group.length>1?'s':''}</small></header><div>${group.slice(page*size(t),page*size(t)+size(t)).map(p=>{const owned=!!state.counts[p.id];return `<button type="button" class="zone-entry ${owned?'':'undiscovered'}" style="--pokemon-color:${typeColor(types[p.id][0])}" data-zone-detail="${p.id}" ${owned?'':'disabled'} aria-label="${p.name}, ${TIER_NAMES[t]}, ${odds(p)}, ${owned?'découvert, ouvrir le profil':'à découvrir'}"><span class="zone-entry-art"><img src="${sprite(p.id)}" alt="" loading="lazy"></span><span class="zone-entry-body"><small>#${String(p.id).padStart(3,'0')} ${owned?'· ✓':''}</small><strong>${p.name}</strong><span class="catalog-types">${typeBadges(p.id)}</span><span class="zone-entry-chance">${(p.probability*100).toLocaleString('fr-FR',{maximumFractionDigits:p.probability<0.001?4:2})} %</span><small>${odds(p)}</small><small>${owned?'Capturé ×'+fmt(state.counts[p.id]):'À découvrir'}</small></span></button>`;}).join('')||`<p class="catalog-empty">${!available?'Absent de cette zone':!group.length?'Aucun résultat avec ces filtres':'Fin de cette catégorie · reviens à la page 1'}</p>`}</div></section>`;}).join('');
 $('[data-page-label]').textContent='Page '+(page+1)+' / '+pages;$('[data-page="-1"]').disabled=page===0;$('[data-page="1"]').disabled=page===pages-1;root.querySelectorAll('[data-status]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.status===status)));
 }
 root.oninput=e=>{if(e.target.matches('[data-search]')){query=e.target.value;page=0;render();}};root.onchange=e=>{if(e.target.matches('[data-type]'))type=e.target.value;else if(e.target.matches('[data-tier]'))tier=e.target.value;else if(e.target.matches('[data-sort]'))sort=e.target.value;else return;page=0;render();};root.onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.status){status=b.dataset.status;page=0;render();}else if(b.dataset.page){page+=+b.dataset.page;render();}else if(b.dataset.zoneDetail)onProfile(+b.dataset.zoneDetail);};render();return {refresh:render};
}
